'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var hasProp = require( '@stdlib/assert/has-property' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var isObject = require( '@stdlib/assert/is-object' );
var Value = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Value, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor returns an instance which has a `color` property', function test( t ) {
	var v;

	v = new Value();
	t.strictEqual( hasOwnProp( v, 'color' ), false, 'returns expected value' );
	t.strictEqual( hasProp( v, 'color' ), true, 'returns expected value' );
	t.strictEqual( isUndefined( v.color ), true, 'returns expected value' );

	v = new Value({
		'color': {
			'r': {
				'value': 255
			},
			'g': {
				'value': 0
			},
			'b': {
				'value': 0
			}
		}
	});
	t.strictEqual( isObject( v.color ), true, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `color` property which throws an error if set to an invalid value', function test( t ) {
	var values;
	var i;

	values = [
		5,
		'beep',
		'boop',
		NaN,
		null,
		true,
		false,
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var v = new Value();
			v.color = value;
		};
	}
});

tape( 'the constructor returns an instance having a `color` property', function test( t ) {
	var expected;
	var v;

	v = new Value();
	t.strictEqual( isUndefined( v.color ), true, 'returns expected value' );

	v = new Value({
		'color': {
			'r': {
				'value': 255
			},
			'g': {
				'value': 0
			},
			'b': {
				'value': 0
			}
		}
	});

	expected = {
		'r': {
			'value': 255
		},
		'g': {
			'value': 0
		},
		'b': {
			'value': 0
		}
	};
	t.deepEqual( v.color, expected, 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having a `color` property which can be set to a valid value', function test( t ) {
	var expected;
	var v;

	v = new Value();

	v.color = {
		'r': {
			'value': 255
		},
		'g': {
			'value': 0
		},
		'b': {
			'value': 0
		}
	};

	expected = {
		'r': {
			'value': 255
		},
		'g': {
			'value': 0
		},
		'b': {
			'value': 0
		}
	};
	t.deepEqual( v.color, expected, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance which emits an event when the `color` property is set to a new value', function test( t ) {
	var count;
	var obj1;
	var obj2;
	var v;

	v = new Value();
	count = 0;

	v.on( 'change', onChange );

	obj1 = {
		'r': {
			'value': 255
		},
		'g': {
			'value': 0
		},
		'b': {
			'value': 0
		}
	};
	v.color = obj1;
	t.strictEqual( count, 1, 'returns expected value' );

	obj2 = {
		'r': {
			'value': 0
		},
		'g': {
			'value': 0
		},
		'b': {
			'value': 255
		}
	};
	v.color = obj2;
	t.strictEqual( count, 2, 'returns expected value' );

	// Setting to the same value should not emit an event:
	v.color = obj2;
	t.strictEqual( count, 2, 'returns expected value' );

	t.end();

	function onChange() {
		count += 1;
	}
});
